#[test]
fn liters_per100_kilometers() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = 100.0 / x;
        assert_close(
            FuelEfficiency::from_liters_per100_kilometers(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = 100.0 / x;
        assert_close(
            FuelEfficiency::from_base(base).as_liters_per100_kilometers(),
            back,
            F64_TOL,
        );
        assert_close(
            FuelEfficiency::from_liters_per100_kilometers(v).as_liters_per100_kilometers(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            FuelEfficiency::from_liters_per100_kilometers(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            FuelEfficiency::from_base(base as f32).as_liters_per100_kilometers() as f64,
            back,
            F32_TOL,
        );
    }
}

