fn unit_metadata() {
    let info = FuelEfficiency::<f64>::INFO;
    assert_eq!(info.name, "FuelEfficiency");
    assert_eq!(info.units.len(), FuelEfficiencyUnit::ALL.len());
    for (&unit, unit_info) in FuelEfficiencyUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, FuelEfficiencyUnit::KilometerPerLiter.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        FuelEfficiency::new(v, FuelEfficiencyUnit::LiterPer100Kilometers),
        FuelEfficiency::from_liters_per100_kilometers(v)
    );
    assert_eq!(
        FuelEfficiency::from_base(v).convert_to(FuelEfficiencyUnit::LiterPer100Kilometers),
        FuelEfficiency::from_base(v).as_liters_per100_kilometers()
    );
    assert_eq!(
        FuelEfficiency::new(v, FuelEfficiencyUnit::MilePerUsGallon),
        FuelEfficiency::from_miles_per_us_gallon(v)
    );
    assert_eq!(
        FuelEfficiency::from_base(v).convert_to(FuelEfficiencyUnit::MilePerUsGallon),
        FuelEfficiency::from_base(v).as_miles_per_us_gallon()
    );
    assert_eq!(
        FuelEfficiency::new(v, FuelEfficiencyUnit::MilePerUkGallon),
        FuelEfficiency::from_miles_per_uk_gallon(v)
    );
    assert_eq!(
        FuelEfficiency::from_base(v).convert_to(FuelEfficiencyUnit::MilePerUkGallon),
        FuelEfficiency::from_base(v).as_miles_per_uk_gallon()
    );
    assert_eq!(
        FuelEfficiency::new(v, FuelEfficiencyUnit::KilometerPerLiter),
        FuelEfficiency::from_kilometers_per_liter(v)
    );
    assert_eq!(
        FuelEfficiency::from_base(v).convert_to(FuelEfficiencyUnit::KilometerPerLiter),
        FuelEfficiency::from_base(v).as_kilometers_per_liter()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [FuelEfficiency; 4] = [
        FuelEfficiency::const_new(1234.5, FuelEfficiencyUnit::LiterPer100Kilometers),
        FuelEfficiency::const_new(1234.5, FuelEfficiencyUnit::MilePerUsGallon),
        FuelEfficiency::const_new(1234.5, FuelEfficiencyUnit::MilePerUkGallon),
        FuelEfficiency::const_new(1234.5, FuelEfficiencyUnit::KilometerPerLiter),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(FuelEfficiencyUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            FuelEfficiency::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in FuelEfficiencyUnit::ALL {
            assert_eq!(
                FuelEfficiency::const_new(v, unit).as_base().to_bits(),
                FuelEfficiency::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = FuelEfficiency::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            FuelEfficiency::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in FuelEfficiencyUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        FuelEfficiency::from_base(0.0).auto_unit().unit,
        FuelEfficiencyUnit::KilometerPerLiter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "l/100km".parse::<FuelEfficiencyUnit>(),
        Ok(FuelEfficiencyUnit::LiterPer100Kilometers)
    );
    assert_eq!(
        format!("2.5 {}", "l/100km").parse::<FuelEfficiency>(),
        Ok(FuelEfficiency::new(
            2.5,
            FuelEfficiencyUnit::LiterPer100Kilometers
        ))
    );
    assert_eq!(
        "mpg (U.S.)".parse::<FuelEfficiencyUnit>(),
        Ok(FuelEfficiencyUnit::MilePerUsGallon)
    );
    assert_eq!(
        format!("2.5 {}", "mpg (U.S.)").parse::<FuelEfficiency>(),
        Ok(FuelEfficiency::new(
            2.5,
            FuelEfficiencyUnit::MilePerUsGallon
        ))
    );
    assert_eq!(
        "mpg (imp.)".parse::<FuelEfficiencyUnit>(),
        Ok(FuelEfficiencyUnit::MilePerUkGallon)
    );
    assert_eq!(
        format!("2.5 {}", "mpg (imp.)").parse::<FuelEfficiency>(),
        Ok(FuelEfficiency::new(
            2.5,
            FuelEfficiencyUnit::MilePerUkGallon
        ))
    );
    assert_eq!(
        "km/l".parse::<FuelEfficiencyUnit>(),
        Ok(FuelEfficiencyUnit::KilometerPerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "km/l").parse::<FuelEfficiency>(),
        Ok(FuelEfficiency::new(
            2.5,
            FuelEfficiencyUnit::KilometerPerLiter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<FuelEfficiency>(),
        Err(ParseError::UnknownUnit)
    );
}

